package com.lmspilot.notification.domain; import jakarta.persistence.*;import java.time.*;import java.util.*;
@Entity @Table(name="notifications") public class NotificationEntity{@Id public UUID id=UUID.randomUUID();@Column(nullable=false)public UUID userId;@Column(nullable=false,length=80)public String type="GENERAL";@Column(nullable=false,length=240)public String title="";@Column(nullable=false,columnDefinition="text")public String body="";@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)public NotificationChannel channel=NotificationChannel.IN_APP;@Column(nullable=false)public boolean read=false;public Instant readAt;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)public DeliveryStatus deliveryStatus=DeliveryStatus.CREATED;@Column(columnDefinition="text")public String variablesJson="{}";@Column(columnDefinition="text")public String deliveryError;@Column(nullable=false)public int deliveryAttempts=0;public Instant nextAttemptAt;public Instant leaseUntil;@Column(nullable=false)public Instant createdAt=Instant.now();@Column(nullable=false)public Instant updatedAt=Instant.now();public NotificationEntity(){}}
